Problem:
A hospital gives pupil dilation drops using two types of dilation drops, fast-acting eye drops and slow-acting eye drops. The fast-acting eye drops take 5 minutes per patient to adjust the patient’s pupils while the slow-acting eye drops take 25 minutes per patient. Since the fast-acting eye drops are more expensive, at least twice as many patients must be dilated using the slow-acting eye drops than the fast-acting eye drops. However, at least 25 patients must be dilated with the fast-acting eye drops. If the clinic is open for 15000 minutes, maximize the number of patients that can be dilated.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "fast-acting drop patients",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "slow-acting drop patients",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "fast-acting drop patients",
     "coef": 1.0
    },
    {
     "var": "slow-acting drop patients",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "slow_at_least_twice_fast",
    "terms": [
     {
      "var": "slow-acting drop patients",
      "coef": 1.0
     },
     {
      "var": "fast-acting drop patients",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   },
   {
    "name": "fast_minimum",
    "terms": [
     {
      "var": "fast-acting drop patients",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 25.0
   },
   {
    "name": "clinic_time",
    "terms": [
     {
      "var": "fast-acting drop patients",
      "coef": 5.0
     },
     {
      "var": "slow-acting drop patients",
      "coef": 25.0
     }
    ],
    "sense": "<=",
    "rhs": 15000.0
   }
  ]
 },
 "facts": {
  "objective": 817.0,
  "values": {
   "fast-acting drop patients": 272.0,
   "slow-acting drop patients": 545.0
  },
  "binding": [],
  "slack": {
   "slow_at_least_twice_fast": 1.0,
   "fast_minimum": 247.0,
   "clinic_time": 15.0
  },
  "shadow_prices": null
 }
}
